flow.typescript:
// D19 · Part 0~7 · 오늘의 흐름 전체: 동의 → 복제 → 워터마크 → 변형 → 검출 → 삭제 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d19_flow.ts
//   동의 게이트를 통과한 목소리로 복제하고 워터마크를 넣은 뒤 잡음 · 전화 변형 후에도 검출되는지, 마지막에 파일을 지우는지 확인
import { createHash } from "node:crypto";
import { mkdtempSync, rmSync, existsSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

const VOICES: Record<string, { f0: number; depth: number }> = { 나: { f0: 180, depth: 1.0 }, "다른 사람": { f0: 280, depth: 1.5 } }; // 장난감 목소리: 높이와 표현 폭만 다르다
const CONSENT_TEXT = "저는 수업 실습을 위해 제 목소리 복제에 동의합니다";
const THRESHOLD = 0.8; // 같은 사람 판정 기준 (데이터마다 다시 정해야 함)

const speak = (who: string, text: string, seed = 0): Float32Array => generate(text, 0.4, 0.5, seed, VOICES[who]);
const sameSpeaker = (score: number): boolean => score >= THRESHOLD;

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

function consentGate(heard: string, voiceSim: number): { text_ok: boolean; voice_ok: boolean; ok: boolean } {
  // 동의 게이트: 동의 문장을 제대로 말했고(받아쓰기) + 같은 사람 목소리여야 통과
  const textOk = cer(CONSENT_TEXT, heard) / 100 <= 0.3;
  const voiceOk = sameSpeaker(voiceSim);
  return { text_ok: textOk, voice_ok: voiceOk, ok: textOk && voiceOk };
}

type Gate = ReturnType<typeof consentGate>;
type ConsentRecord = { user_id: string; purpose: string; scope: string; created: string; expires: string; audio_sha256: string; gate: Gate; revoked: boolean };

function makeRecord(userId: string, audio: Float32Array, gate: Gate, days = 1, now: Date = new Date()): ConsentRecord {
  // 동의 기록: 누가 · 무엇을 · 언제까지 · 동의 녹음의 지문(sha256)
  const iso = (d: Date): string => d.toISOString().slice(0, 19);
  return {
    user_id: userId, purpose: "D19 수업 실습: 본인 목소리 복제 체험", scope: "이 실습 안에서만 · 외부 공유 금지",
    created: iso(now), expires: iso(new Date(now.getTime() + days * 86400000)),
    audio_sha256: createHash("sha256").update(new Uint8Array(audio.buffer, audio.byteOffset, audio.byteLength)).digest("hex"),
    gate, revoked: false,
  };
}

function lowpass(y: Float32Array, cutoff: number, sr: number = SR, taps = 201): Float32Array {
  // 창 함수 sinc 저역 통과 필터: cutoff Hz 위를 잘라낸다 (전화 음질 흉내)
  const c = (taps - 1) / 2;
  const sinc = (x: number): number => (x === 0 ? 1 : Math.sin(Math.PI * x) / (Math.PI * x));
  const h = Array.from({ length: taps }, (_, i) => sinc(((2 * cutoff) / sr) * (i - c)) * (0.54 - 0.46 * Math.cos((2 * Math.PI * i) / (taps - 1))));
  const sum = h.reduce((a, b) => a + b, 0);
  const out = new Float32Array(y.length);
  for (let i = 0; i < y.length; i++) {
    let s = 0;
    for (let k = 0; k < taps; k++) {
      const j = i + k - c;
      if (j >= 0 && j < y.length) s += h[taps - 1 - k] * y[j];
    }
    out[i] = s / sum;
  }
  return out;
}

function addNoise(y: Float32Array, snrDb: number, seed = 0): Float32Array {
  // 신호 대 잡음비가 snr_db가 되도록 흰 잡음을 더한다 (전력 비는 10 x log10)
  const r = rng(seed);
  const n = Float64Array.from({ length: y.length }, () => gauss(r));
  const pSig = y.reduce((a, v) => a + v * v, 0) / y.length;
  const pNoise = n.reduce((a, v) => a + v * v, 0) / n.length;
  const g = Math.sqrt(pSig / (pNoise * 10 ** (snrDb / 10)));
  return Float32Array.from(y, (v, i) => v + n[i] * g);
}

function snrDb(clean: Float32Array, noisy: Float32Array): number {
  let ps = 0;
  let pn = 0;
  for (let i = 0; i < clean.length; i++) {
    ps += clean[i] ** 2;
    pn += (noisy[i] - clean[i]) ** 2;
  }
  return 10 * Math.log10(ps / pn);
}

function resample(y: Float32Array, factor: number): Float32Array {
  // factor배 빠르게 (선형 보간). 속도와 음높이가 함께 바뀐다
  const n = Math.ceil((y.length - 1) / factor);
  return Float32Array.from({ length: n }, (_, i) => {
    const p = i * factor;
    const k = Math.floor(p);
    return y[k] + (y[Math.min(k + 1, y.length - 1)] - y[k]) * (p - k);
  });
}

const ref = speak("나", "기준 목소리 문장입니다", 1);
const mine = speak("나", CONSENT_TEXT, 2);
const gate = consentGate(CONSENT_TEXT, speakerSim(mine, ref)); // 1) 동의 게이트
const record = makeRecord("student01", mine, gate); // 2) 동의 기록
if (!gate.ok) throw new Error("동의 확인 실패 -> 복제하지 않음");
const clone = applyWatermark(speak("나", "오늘 수업 정말 재미있었어요. 다음 시간에 또 만나요.", 5)); // 3) 복제 + 워터마크
const scores: Record<string, number> = {
  "원본": getWatermark(clone),
  "잡음 20dB": getWatermark(addNoise(clone, 20)),
  "전화 3.8kHz": getWatermark(lowpass(clone, 3800)),
  "앞 1초 자르기": getWatermark(clone.slice(SR)),
}; // 4) 변형 후 검출
console.log("워터마크 점수:", JSON.stringify(Object.fromEntries(Object.entries(scores).map(([k, v]) => [k, +v.toFixed(2)]))));
const work = mkdtempSync(join(tmpdir(), "d19-")); // 5) 임시 파일 저장 후 삭제 (수업이 끝나면 반드시)
writeFileSync(join(work, "clone.f32"), new Uint8Array(clone.buffer));
rmSync(work, { recursive: true, force: true });
console.log("남은 동의 기록 (해시만):", record.audio_sha256.slice(0, 16) + "...", "· 임시 폴더 남음:", existsSync(work));
check(gate.ok && scores["원본"] > 0.9 && scores["잡음 20dB"] > 0.8 && scores["전화 3.8kHz"] >= 0.5
  && scores["앞 1초 자르기"] < 0.5 && !existsSync(work));

risk.typescript:
// D19 · Part 1 · 이 사용은 괜찮을까? 위험 판정 규칙 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d19_risk.ts
//   동의 · AI 고지 · 사칭 · 금전 요구 네 가지로 사용 사례를 가능 / 조건부 / 금지로 가른다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// (이름, 본인 동의, AI 고지, 사칭 의도, 금전 요구)
const CASES: [string, boolean, boolean, boolean, boolean][] = [
  ["내 목소리로 만든 수업 안내 방송", true, true, false, false],
  ["게임 NPC에 배우 목소리 (계약 · 동의)", true, true, false, false],
  ["세상을 떠난 가족 목소리 복원 (유족 동의)", true, false, false, false],
  ["유명인 목소리로 광고 (동의 없음)", false, true, false, false],
  ["자녀 목소리로 부모에게 송금 요청 전화", true, false, true, true],
];

function verdict(consent: boolean, disclosed: boolean, impersonation: boolean, money: boolean): string {
  // 금지 조건부터 본다: 사칭 · 금전 요구 · 동의 없음은 금지, 고지 없음은 조건부
  if (impersonation || money || !consent) return "금지";
  return disclosed ? "가능" : "조건부 (AI 고지 필요)";
}

const results = CASES.map(([name, ...flags]) => {
  const v = verdict(...flags);
  console.log(`${v.padEnd(14)} ${name}`);
  return v;
});
check(results.join("|") === ["가능", "가능", "조건부 (AI 고지 필요)", "금지", "금지"].join("|"), "동의 없음 · 사칭 · 금전 요구는 금지, 고지만 빠지면 조건부");

law.typescript:
// D19 · Part 1 · 법 · 제도가 요구하는 것: 동의 기록 점검기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d19_law.ts
//   동의 기록이 갖춰야 할 항목(목적 · 범위 · 만료 · 지문)과 철회 · 만료 · 보관 기간을 코드로 점검한다 (일반 원칙, 특정 법 조항 아님)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Rec = { [k: string]: string | boolean | undefined };
const REQUIRED = ["user_id", "purpose", "scope", "created", "expires", "audio_sha256"];
const MAX_RETENTION_DAYS = 30; // 예시: 동의 녹음 보관 상한
const DAY = 86400000;

function audit(record: Rec, now: Date, used = false): string[] {
  // 동의 기록의 문제점 목록. 비어 있으면 통과
  const problems = REQUIRED.filter((k) => !record[k]).map((k) => `항목 없음: ${k}`);
  if (problems.length) return problems;
  const created = new Date(record.created as string).getTime();
  const expires = new Date(record.expires as string).getTime();
  if (expires <= created) problems.push("만료일이 생성일보다 빠름");
  if (Math.floor((expires - created) / DAY) > MAX_RETENTION_DAYS) problems.push(`보관 기간 ${MAX_RETENTION_DAYS}일 초과`);
  if (used && now.getTime() > expires) problems.push("만료된 동의로 사용함");
  if (used && record.revoked) problems.push("철회된 동의로 사용함");
  return problems;
}

const now = new Date("2026-11-20T10:00:00Z");
const iso = (d: Date): string => d.toISOString().slice(0, 19);
const good: Rec = { user_id: "student01", purpose: "수업 실습", scope: "이 실습 안에서만", created: iso(now), expires: iso(new Date(now.getTime() + DAY)), audio_sha256: "ab".repeat(32) };
const cases: Record<string, [Rec, Date, boolean]> = {
  "정상": [good, now, true],
  "목적 빠짐": [{ ...good, purpose: "" }, now, true],
  "너무 긴 보관": [{ ...good, expires: iso(new Date(now.getTime() + 90 * DAY)) }, now, false],
  "만료 후 사용": [good, new Date(now.getTime() + 3 * DAY), true],
  "철회 후 사용": [{ ...good, revoked: true }, now, true],
};
const out: Record<string, string[]> = {};
for (const [name, [rec, t, used]] of Object.entries(cases)) {
  out[name] = audit(rec, t, used);
  console.log(`${name}: ${out[name].length ? JSON.stringify(out[name]) : "문제 없음"}`);
}
check(out["정상"].length === 0 && out["목적 빠짐"].join() === "항목 없음: purpose" && out["너무 긴 보관"].join() === "보관 기간 30일 초과"
  && out["만료 후 사용"].join() === "만료된 동의로 사용함" && out["철회 후 사용"].join() === "철회된 동의로 사용함");

consent.typescript:
// D19 · Part 2 · 동의 게이트와 동의 기록 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d19_consent.ts
//   동의 문장을 제대로 말했는지(CER ≤ 0.30) + 같은 사람 목소리인지 둘 다 통과해야 하고, 통과하면 지문(sha256)이 든 기록을 남긴다
import { createHash } from "node:crypto";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

const VOICES: Record<string, { f0: number; depth: number }> = { 나: { f0: 180, depth: 1.0 }, "다른 사람": { f0: 280, depth: 1.5 } }; // 장난감 목소리: 높이와 표현 폭만 다르다
const CONSENT_TEXT = "저는 수업 실습을 위해 제 목소리 복제에 동의합니다";
const THRESHOLD = 0.8; // 같은 사람 판정 기준 (데이터마다 다시 정해야 함)

const speak = (who: string, text: string, seed = 0): Float32Array => generate(text, 0.4, 0.5, seed, VOICES[who]);
const sameSpeaker = (score: number): boolean => score >= THRESHOLD;

function consentGate(heard: string, voiceSim: number): { text_ok: boolean; voice_ok: boolean; ok: boolean } {
  // 동의 게이트: 동의 문장을 제대로 말했고(받아쓰기) + 같은 사람 목소리여야 통과
  const textOk = cer(CONSENT_TEXT, heard) / 100 <= 0.3;
  const voiceOk = sameSpeaker(voiceSim);
  return { text_ok: textOk, voice_ok: voiceOk, ok: textOk && voiceOk };
}

type Gate = ReturnType<typeof consentGate>;
type ConsentRecord = { user_id: string; purpose: string; scope: string; created: string; expires: string; audio_sha256: string; gate: Gate; revoked: boolean };

function makeRecord(userId: string, audio: Float32Array, gate: Gate, days = 1, now: Date = new Date()): ConsentRecord {
  // 동의 기록: 누가 · 무엇을 · 언제까지 · 동의 녹음의 지문(sha256)
  const iso = (d: Date): string => d.toISOString().slice(0, 19);
  return {
    user_id: userId, purpose: "D19 수업 실습: 본인 목소리 복제 체험", scope: "이 실습 안에서만 · 외부 공유 금지",
    created: iso(now), expires: iso(new Date(now.getTime() + days * 86400000)),
    audio_sha256: createHash("sha256").update(new Uint8Array(audio.buffer, audio.byteOffset, audio.byteLength)).digest("hex"),
    gate, revoked: false,
  };
}

const ref = speak("나", "기준 목소리 문장입니다", 1); // 기준 목소리 (본인 등록)
const mine = speak("나", CONSENT_TEXT, 2); // ① 나 + 동의 문장
const other = speak("다른 사람", CONSENT_TEXT, 3); // ② 다른 사람 + 동의 문장
const held = speak("나", "전혀 다른 문장입니다", 4); // ③ 나 + 다른 문장 (동의로 착각하면 안 됨)
// 받아쓰기(ASR) 대신: 말한 문장을 그대로 받아쓴 것으로 가정 (①은 한 글자 틀리게)
const cases: [string, Float32Array, string][] = [
  ["① 나 + 동의 문장", mine, CONSENT_TEXT.replace("동의", "동이")],
  ["② 다른 사람 + 동의 문장", other, CONSENT_TEXT],
  ["③ 나 + 다른 문장", held, "전혀 다른 문장입니다"],
];
const gates: Record<string, Gate> = {};
for (const [name, y, heard] of cases) {
  const s = speakerSim(y, ref);
  gates[name] = consentGate(heard, s);
  console.log(`${name}: 화자유사도 ${s.toFixed(2)} · CER ${(cer(CONSENT_TEXT, heard) / 100).toFixed(2)} ->`, JSON.stringify(gates[name]));
}

const record = makeRecord("student01", mine, gates["① 나 + 동의 문장"]);
console.log(JSON.stringify({ user_id: record.user_id, expires: record.expires, revoked: record.revoked }), "지문", record.audio_sha256.slice(0, 16) + "...");
const sha = createHash("sha256").update(new Uint8Array(mine.buffer, mine.byteOffset, mine.byteLength)).digest("hex");
check(gates["① 나 + 동의 문장"].ok && !gates["② 다른 사람 + 동의 문장"].ok && !gates["③ 나 + 다른 문장"].ok
  && consentGate(CONSENT_TEXT, 0.95).ok && !consentGate(CONSENT_TEXT, 0.1).ok
  && record.audio_sha256 === sha && record.revoked === false);

