  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

const SPEAKERS: Record<string, [number, number]> = { A: [170, 0.8], B: [200, 1.0], C: [240, 1.2], D: [290, 1.5] };
const TEXTS = ["안녕하세요 반갑습니다", "오늘 날씨가 정말 좋네요", "회의는 세 시에 시작합니다"];

function utter(name: string, k: number): Float32Array {
  const [f0, depth] = SPEAKERS[name];
  return generate(TEXTS[k % 3], 0.4, 0.5, 10 + k, { f0, depth });
}

const e = embed(utter("A", 0));
console.log("화자 벡터 모양:", [e.length], "· 자기 자신과의 유사도:", speakerSim(utter("A", 0), utter("A", 0)).toFixed(4));
const names = Object.keys(SPEAKERS);
const same = names.map((n) => speakerSim(utter(n, 0), utter(n, 1))); // 같은 사람, 다른 문장
const diff = names.flatMap((a) => names.filter((b) => a !== b).map((b) => speakerSim(utter(a, 0), utter(b, 1)))); // 다른 사람
console.log(`같은 사람 유사도 ${Math.min(...same).toFixed(2)} ~ ${Math.max(...same).toFixed(2)} · 다른 사람 ${Math.min(...diff).toFixed(2)} ~ ${Math.max(...diff).toFixed(2)}`);
for (const thr of [0.5, 0.6, 0.7, 0.8, 0.9]) {
  const frr = same.filter((s) => s < thr).length / same.length; // 본인인데 거부한 비율
  const far = diff.filter((d) => d >= thr).length / diff.length; // 남인데 통과시킨 비율
  console.log(`  임계값 ${thr}: 본인 거부 ${(frr * 100).toFixed(0)}% · 남 통과 ${(far * 100).toFixed(0)}%`);
}
const avg = (x: number[]): number => x.reduce((a, b) => a + b, 0) / x.length;
check(e.length === 3 && Math.abs(speakerSim(utter("A", 0), utter("A", 0)) - 1) < 1e-9
  && Math.min(...same) > 0.8 && Math.min(...diff) < 0.8 && avg(same) > avg(diff),
  "같은 사람 유사도가 다른 사람보다 높고, 기준 0.8이 둘을 가르는지 확인");

wm.typescript:
// D19 · Part 5 · 워터마크는 얼마나 버티나: 변형 공격 표 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d19_wm.ts
//   복제 · 내 녹음 · 워터마크를 넣은 내 녹음을 볼륨 · 잡음 · 전화 · 자르기 · 속도 · 음높이로 변형해 검출 점수표를 만든다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

function lowpass(y: Float32Array, cutoff: number, sr: number = SR, taps = 201): Float32Array {
  // 창 함수 sinc 저역 통과 필터: cutoff Hz 위를 잘라낸다 (전화 음질 흉내)
  const c = (taps - 1) / 2;
  const sinc = (x: number): number => (x === 0 ? 1 : Math.sin(Math.PI * x) / (Math.PI * x));
  const h = Array.from({ length: taps }, (_, i) => sinc(((2 * cutoff) / sr) * (i - c)) * (0.54 - 0.46 * Math.cos((2 * Math.PI * i) / (taps - 1))));
  const sum = h.reduce((a, b) => a + b, 0);
  const out = new Float32Array(y.length);
  for (let i = 0; i < y.length; i++) {
    let s = 0;
    for (let k = 0; k < taps; k++) {
      const j = i + k - c;
      if (j >= 0 && j < y.length) s += h[taps - 1 - k] * y[j];
    }
    out[i] = s / sum;
  }
  return out;
}

function addNoise(y: Float32Array, snrDb: number, seed = 0): Float32Array {
  // 신호 대 잡음비가 snr_db가 되도록 흰 잡음을 더한다 (전력 비는 10 x log10)
  const r = rng(seed);
  const n = Float64Array.from({ length: y.length }, () => gauss(r));
  const pSig = y.reduce((a, v) => a + v * v, 0) / y.length;
  const pNoise = n.reduce((a, v) => a + v * v, 0) / n.length;
  const g = Math.sqrt(pSig / (pNoise * 10 ** (snrDb / 10)));
  return Float32Array.from(y, (v, i) => v + n[i] * g);
}

function snrDb(clean: Float32Array, noisy: Float32Array): number {
  let ps = 0;
  let pn = 0;
  for (let i = 0; i < clean.length; i++) {
    ps += clean[i] ** 2;
    pn += (noisy[i] - clean[i]) ** 2;
  }
  return 10 * Math.log10(ps / pn);
}

function resample(y: Float32Array, factor: number): Float32Array {
  // factor배 빠르게 (선형 보간). 속도와 음높이가 함께 바뀐다
  const n = Math.ceil((y.length - 1) / factor);
  return Float32Array.from({ length: n }, (_, i) => {
    const p = i * factor;
    const k = Math.floor(p);
    return y[k] + (y[Math.min(k + 1, y.length - 1)] - y[k]) * (p - k);
  });
}

const ATTACKS: Record<string, (y: Float32Array) => Float32Array> = {
  "원본": (y) => y,
  "볼륨 x0.5": (y) => y.map((v) => 0.5 * v),
  "앞 1초 자르기": (y) => y.slice(SR),
  "잡음 30dB": (y) => addNoise(y, 30),
  "잡음 20dB": (y) => addNoise(y, 20),
  "잡음 10dB": (y) => addNoise(y, 10),
  "전화 3.8kHz": (y) => lowpass(y, 3800),
  "속도 1.1x": (y) => resample(y, 1.1),
  "음높이 +2": (y) => resample(y, 2 ** (2 / 12)),
};

const clone = generate("오늘 수업 정말 재미있었어요 다음 시간에 또 만나요", 0.4, 0.5, 1, { f0: 180, depth: 1.0 }); // 복제된 소리(워터마크 없음)
const mine = generate("저는 수업 실습을 위해 제 목소리를 녹음합니다", 0.4, 0.5, 2, { f0: 200, depth: 1.0 });
const SOURCES: Record<string, Float32Array> = { "복제 (워터마크 없음)": clone, "내 녹음 (원본)": mine, "내 녹음 + 워터마크": applyWatermark(mine) };
const names = Object.keys(ATTACKS);
console.log("".padEnd(22) + names.map((n) => n.slice(0, 6).padStart(7)).join(" "));
const table: Record<string, Record<string, number>> = {};
for (const [src, y] of Object.entries(SOURCES)) {
  table[src] = Object.fromEntries(names.map((a) => [a, getWatermark(ATTACKS[a](y))]));
  console.log(src.padEnd(22) + names.map((a) => table[src][a].toFixed(2).padStart(7)).join(" "));
}
const wm = table["내 녹음 + 워터마크"];
console.log("버티는 변형:", names.filter((a) => wm[a] >= 0.5).join(", "), "· 못 버티는 변형:", names.filter((a) => wm[a] < 0.5).join(", "));
check(Object.values(table["복제 (워터마크 없음)"]).every((v) => v < 0.5) && Object.values(table["내 녹음 (원본)"]).every((v) => v < 0.5)
  && wm["원본"] > 0.9 && wm["볼륨 x0.5"] > 0.9 && wm["잡음 20dB"] > 0.8 && wm["전화 3.8kHz"] >= 0.5
  && wm["앞 1초 자르기"] < 0.5 && wm["속도 1.1x"] < 0.5 && wm["음높이 +2"] < 0.5,
  "워터마크가 있을 때만 높고, 자르기 · 속도 · 음높이 변형에는 약해야 해요");

