    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function styleFrom(y: Float32Array): { f0: number; depth: number } {
  // 참고 음성에서 '말투 조건'을 뽑는다: 목소리 높이 + 표현 폭 (진짜는 화자 임베딩 · 참고 토큰)
  const p = prosody(y);
  return { f0: p.pitchHz, depth: p.rangeSt / 7.0 }; // 7 = 기본 손잡이(exaggeration 0.5)의 음높이 폭(반음)
}

function embed(y: Float32Array): number[] {
  // 화자 특징 3개: 높이(옥타브) · 폭 · 세기 변화
  const p = prosody(y);
  return [Math.log2(p.pitchHz / 200), p.rangeSt / 12, p.energyDb / 6];
}

function speakerSim(a: Float32Array, b: Float32Array): number {
  // 특징 사이 거리가 가까울수록 1에 가까운 유사도
  const ea = embed(a);
  const eb = embed(b);
  return 1 / (1 + Math.sqrt(ea.reduce((s, v, i) => s + (v - eb[i]) ** 2, 0)));
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

const VOICES: Record<string, { f0: number; depth: number }> = { 나: { f0: 180, depth: 1.0 }, "다른 사람": { f0: 280, depth: 1.5 } }; // 장난감 목소리: 높이와 표현 폭만 다르다
const CONSENT_TEXT = "저는 수업 실습을 위해 제 목소리 복제에 동의합니다";
const THRESHOLD = 0.8; // 같은 사람 판정 기준 (데이터마다 다시 정해야 함)

const speak = (who: string, text: string, seed = 0): Float32Array => generate(text, 0.4, 0.5, seed, VOICES[who]);
const sameSpeaker = (score: number): boolean => score >= THRESHOLD;

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

function consentGate(heard: string, voiceSim: number): { text_ok: boolean; voice_ok: boolean; ok: boolean } {
  // 동의 게이트: 동의 문장을 제대로 말했고(받아쓰기) + 같은 사람 목소리여야 통과
  const textOk = cer(CONSENT_TEXT, heard) / 100 <= 0.3;
  const voiceOk = sameSpeaker(voiceSim);
  return { text_ok: textOk, voice_ok: voiceOk, ok: textOk && voiceOk };
}

type Gate = ReturnType<typeof consentGate>;
type ConsentRecord = { user_id: string; purpose: string; scope: string; created: string; expires: string; audio_sha256: string; gate: Gate; revoked: boolean };

function makeRecord(userId: string, audio: Float32Array, gate: Gate, days = 1, now: Date = new Date()): ConsentRecord {
  // 동의 기록: 누가 · 무엇을 · 언제까지 · 동의 녹음의 지문(sha256)
  const iso = (d: Date): string => d.toISOString().slice(0, 19);
  return {
    user_id: userId, purpose: "D19 수업 실습: 본인 목소리 복제 체험", scope: "이 실습 안에서만 · 외부 공유 금지",
    created: iso(now), expires: iso(new Date(now.getTime() + days * 86400000)),
    audio_sha256: createHash("sha256").update(new Uint8Array(audio.buffer, audio.byteOffset, audio.byteLength)).digest("hex"),
    gate, revoked: false,
  };
}

const BLOCK_WORDS = ["송금", "계좌", "비밀번호", "인증번호", "급하게 돈"];
const DISCLOSURE = "이 음성은 인공지능으로 만든 음성입니다.";
const LOG: { time: string; user_id: string; text_sha256: string; audio_sha256: string }[] = [];
const sha = (b: Uint8Array | string): string => createHash("sha256").update(b).digest("hex").slice(0, 16);

function responsibleClone(consents: Record<string, ConsentRecord>, userId: string, text: string, now: Date): Float32Array {
  // 복제 요청이 지나야 하는 관문들. 하나라도 걸리면 합성하지 않는다
  const c = consents[userId];
  if (!c) throw new Error("동의 기록 없음");
  if (c.revoked) throw new Error("동의가 철회됨"); // 1) 철회된 동의
  if (BLOCK_WORDS.some((w) => text.includes(w))) throw new Error("금지된 내용 (사칭 · 금융 요구)"); // 2) 사칭 · 금융 요구 금지어
  if (!c.gate.ok) throw new Error("동의 확인 실패"); // 3) 동의 게이트 미통과
  if (now.getTime() > new Date(c.expires + "Z").getTime()) throw new Error("동의 만료"); // 4) 만료
  const notice = generate(DISCLOSURE, 0.3, 0.5, 0); // 5) 고지는 기본 목소리로
  const speech = speak("나", text, 1);
  const joined = new Float32Array(notice.length + Math.floor(0.4 * SR) + speech.length);
  joined.set(notice, 0);
  joined.set(speech, notice.length + Math.floor(0.4 * SR));
  const out = applyWatermark(joined); // 6) 워터마크
  if (getWatermark(out) < 0.5) throw new Error("워터마크 확인 실패 -> 내보내지 않음");
  LOG.push({ time: now.toISOString().slice(0, 19), user_id: userId, text_sha256: sha(text), audio_sha256: sha(new Uint8Array(out.buffer)) });
  return out; // 7) 기록을 남기고 내보냄
}

function attempt(label: string, consents: Record<string, ConsentRecord>, userId: string, text: string, now: Date): string {
  try {
    const y = responsibleClone(consents, userId, text, now);
    console.log(`[합성] ${label}: ${(y.length / SR).toFixed(1)}초 · 워터마크 ${getWatermark(y).toFixed(2)}`);
    return "합성";
  } catch (e) {
    console.log(`[거부] ${label}: ${(e as Error).message}`);
    return (e as Error).message;
  }
}

const now = new Date("2026-11-20T10:00:00Z");
const ref = speak("나", "기준 목소리 문장입니다", 1);
const mine = speak("나", CONSENT_TEXT, 2);
const gate = consentGate(CONSENT_TEXT, speakerSim(mine, ref));
const consents: Record<string, ConsentRecord> = { student01: makeRecord("student01", mine, gate, 1, now) };

const r1 = attempt("① 정상 요청", consents, "student01", "오늘 수업 정말 재미있었어요. 다음 시간에 또 만나요.", now);
const r2 = attempt("② 금지 내용", consents, "student01", "엄마, 급하게 돈이 필요해서 그러는데 계좌로 송금해 줘.", now);
const r4 = attempt("③ 만료 뒤 요청", consents, "student01", "오늘 수업 정말 재미있었어요.", new Date(now.getTime() + 2 * 86400000));
consents["student01"].revoked = true; // 학생이 동의를 철회
const r3 = attempt("④ 철회 후 요청", consents, "student01", "오늘 수업 정말 재미있었어요.", now);
const r5 = attempt("⑤ 동의 기록 없는 사람", consents, "student02", "안녕하세요.", now);
console.log("기록:", JSON.stringify(LOG));
check(r1 === "합성" && r2.includes("금지") && r4.includes("만료") && r3.includes("철회") && r5.includes("기록 없음") && LOG.length === 1,
  "합성은 정상 요청 1건뿐이고 나머지는 거부 사유가 달라야 해요");

